127	void AbstractCommand::useFasterRequest(
128	    const std::shared_ptr<Request>& fasterRequest)
129	{
130	  A2_LOG_INFO(fmt("CUID#%" PRId64 " - Use faster Request hostname=%s, port=%u",
131	                  getCuid(), fasterRequest->getHost().c_str(),
132	                  fasterRequest->getPort()));
133	  // Cancel current Request object and use faster one.
134	  fileEntry_->removeRequest(req_);
135	  e_->setNoWait(true);
136	  e_->addCommand(
137	      InitiateConnectionCommandFactory::createInitiateConnectionCommand(
138	          getCuid(), fasterRequest, fileEntry_, requestGroup_, e_));
139	}
