141	bool AbstractCommand::shouldProcess() const
142	{
143	  if (checkSocketIsReadable_) {
144	    if (readEventEnabled()) {
145	      return true;
146	    }
147	
148	    if (socketRecvBuffer_ && !socketRecvBuffer_->bufferEmpty()) {
149	      return true;
150	    }
151	
152	    if (socket_ && socket_->getRecvBufferedLength()) {
153	      return true;
154	    }
155	  }
156	
157	  if (checkSocketIsWritable_ && writeEventEnabled()) {
158	    return true;
159	  }
160	
161	#ifdef ENABLE_ASYNC_DNS
162	  const auto resolverChecked = asyncNameResolverMan_->resolverChecked();
163	  if (resolverChecked && asyncNameResolverMan_->getStatus() != 0) {
164	    return true;
165	  }
166	
167	  if (!checkSocketIsReadable_ && !checkSocketIsWritable_ && !resolverChecked) {
168	    return true;
169	  }
170	#else  // ENABLE_ASYNC_DNS
171	  if (!checkSocketIsReadable_ && !checkSocketIsWritable_) {
172	    return true;
173	  }
174	#endif // ENABLE_ASYNC_DNS
175	
176	  return noCheck();
177	}
178	
179	bool AbstractCommand::execute()
180	{
181	  A2_LOG_DEBUG(fmt("CUID#%" PRId64
182	                   " - socket: read:%d, write:%d, hup:%d, err:%d",
183	                   getCuid(), readEventEnabled(), writeEventEnabled(),
184	                   hupEventEnabled(), errorEventEnabled()));
185	  try {
186	    if (requestGroup_->downloadFinished() || requestGroup_->isHaltRequested()) {
187	      return true;
188	    }
189	
190	    if (req_ && req_->removalRequested()) {
191	      A2_LOG_DEBUG(fmt("CUID#%" PRId64
192	                       " - Discard original URI=%s because it is"
193	                       " requested.",
194	                       getCuid(), req_->getUri().c_str()));
195	      return prepareForRetry(0);
196	    }
197	
198	    auto sm = getSegmentMan();
199	
200	    if (getPieceStorage()) {
201	      segments_.clear();
202	      sm->getInFlightSegment(segments_, getCuid());
203	
204	      if (req_ && segments_.empty()) {
205	        // This command previously has assigned segments, but it is
206	        // canceled. So discard current request chain.  Plus, if no
207	        // segment is available when http pipelining is used.
208	        A2_LOG_DEBUG(fmt("CUID#%" PRId64
209	                         " - It seems previously assigned segments"
210	                         " are canceled. Restart.",
211	                         getCuid()));
212	        // Request::isPipeliningEnabled() == true means aria2
213	        // accessed the remote server and discovered that the server
214	        // supports pipelining.
215	        if (req_ && req_->isPipeliningEnabled()) {
216	          e_->poolSocket(req_, createProxyRequest(), socket_);
217	        }
218	        return prepareForRetry(0);
219	      }
220	
221	      // TODO it is not needed to check other PeerStats every time.
222	      // Find faster Request when no segment split is allowed.
223	      if (req_ && fileEntry_->countPooledRequest() > 0 &&
224	          requestGroup_->getPendingLength() < calculateMinSplitSize() * 2) {
225	        auto fasterRequest = fileEntry_->findFasterRequest(req_);
226	        if (fasterRequest) {
227	          useFasterRequest(fasterRequest);
228	          return true;
229	        }
230	      }
231	      // Don't use this feature if PREF_MAX_{OVERALL_}DOWNLOAD_LIMIT
232	      // is used or total length is unknown.
233	      if (req_ && fileEntry_->getLength() > 0 &&
234	          e_->getRequestGroupMan()->getMaxOverallDownloadSpeedLimit() == 0 &&
235	          requestGroup_->getMaxDownloadSpeedLimit() == 0 &&
236	          serverStatTimer_.difference(global::wallclock()) >= 10_s) {
237	        serverStatTimer_ = global::wallclock();
238	        std::vector<std::pair<size_t, std::string>> usedHosts;
239	        if (getOption()->getAsBool(PREF_SELECT_LEAST_USED_HOST)) {
240	          getDownloadEngine()->getRequestGroupMan()->getUsedHosts(usedHosts);
241	        }
242	        auto fasterRequest = fileEntry_->findFasterRequest(
243	            req_, usedHosts, e_->getRequestGroupMan()->getServerStatMan());
244	        if (fasterRequest) {
245	          useFasterRequest(fasterRequest);
246	          return true;
247	        }
248	      }
249	    }
250	
251	    if (shouldProcess()) {
252	      checkPoint_ = global::wallclock();
253	
254	      if (!getPieceStorage()) {
255	        return executeInternal();
256	      }
257	
258	      if (!req_ || req_->getMaxPipelinedRequest() == 1 ||
259	          // Why the following condition is necessary? That's because
260	          // For single file download, SegmentMan::getSegment(cuid)
261	          // is more efficient.
262	          getDownloadContext()->getFileEntries().size() == 1) {
263	        size_t maxSegments = req_ ? req_->getMaxPipelinedRequest() : 1;
264	        size_t minSplitSize = calculateMinSplitSize();
265	        while (segments_.size() < maxSegments) {
266	          auto segment = sm->getSegment(getCuid(), minSplitSize);
267	          if (!segment) {
268	            break;
269	          }
270	          segments_.push_back(segment);
271	        }
272	        if (segments_.empty()) {
273	          // TODO socket could be pooled here if pipelining is
274	          // enabled...  Hmm, I don't think if pipelining is enabled
275	          // it does not go here.
276	          A2_LOG_INFO(fmt(MSG_NO_SEGMENT_AVAILABLE, getCuid()));
277	          // When all segments are ignored in SegmentMan, there are
278	          // no URIs available, so don't retry.
279	          if (sm->allSegmentsIgnored()) {
280	            A2_LOG_DEBUG("All segments are ignored.");
281	            // This will execute other idle Commands and let them
282	            // finish quickly.
283	            e_->setRefreshInterval(std::chrono::milliseconds(0));
284	            return true;
285	          }
286	
287	          return prepareForRetry(1);
288	        }
289	      }
290	      else {
291	        // For multi-file downloads
292	        size_t minSplitSize = calculateMinSplitSize();
293	        size_t maxSegments = req_->getMaxPipelinedRequest();
294	        if (segments_.size() < maxSegments) {
295	          sm->getSegment(segments_, getCuid(), minSplitSize, fileEntry_,
296	                         maxSegments);
297	        }
298	        if (segments_.empty()) {
299	          return prepareForRetry(0);
300	        }
301	      }
302	
303	      return executeInternal();
304	    }
305	
306	    if (errorEventEnabled()) {
307	      // older kernel may report "connection refused" here.
308	      auto ss = e_->getRequestGroupMan()->getOrCreateServerStat(
309	          req_->getHost(), req_->getProtocol());
310	      ss->setError();
311	
312	      throw DL_RETRY_EX(
313	          fmt(MSG_NETWORK_PROBLEM, socket_->getSocketError().c_str()));
314	    }
315	
316	    if (checkPoint_.difference(global::wallclock()) >= timeout_) {
317	      // timeout triggers ServerStat error state.
318	      auto ss = e_->getRequestGroupMan()->getOrCreateServerStat(
319	          req_->getHost(), req_->getProtocol());
320	      ss->setError();
321	      // When DNS query was timeout, req_->getConnectedAddr() is
322	      // empty.
323	      if (!req_->getConnectedAddr().empty()) {
324	        // Purging IP address cache to renew IP address.
325	        A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Marking IP address %s as bad",
326	                         getCuid(), req_->getConnectedAddr().c_str()));
327	        e_->markBadIPAddress(req_->getConnectedHostname(),
328	                             req_->getConnectedAddr(),
329	                             req_->getConnectedPort());
330	      }
331	      if (e_->findCachedIPAddress(req_->getConnectedHostname(),
332	                                  req_->getConnectedPort())
333	              .empty()) {
334	        A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - All IP addresses were marked bad."
335	                         " Removing Entry.",
336	                         getCuid()));
337	        e_->removeCachedIPAddress(req_->getConnectedHostname(),
338	                                  req_->getConnectedPort());
339	      }
340	      throw DL_RETRY_EX2(EX_TIME_OUT, error_code::TIME_OUT);
341	    }
342	
343	    addCommandSelf();
344	    return false;
345	  }
346	  catch (DlAbortEx& err) {
347	    requestGroup_->setLastErrorCode(err.getErrorCode(), err.what());
348	    if (req_) {
349	      A2_LOG_ERROR_EX(
350	          fmt(MSG_DOWNLOAD_ABORTED, getCuid(), req_->getUri().c_str()),
351	          DL_ABORT_EX2(fmt("URI=%s", req_->getCurrentUri().c_str()), err));
352	      fileEntry_->addURIResult(req_->getUri(), err.getErrorCode());
353	      if (err.getErrorCode() == error_code::CANNOT_RESUME) {
354	        requestGroup_->increaseResumeFailureCount();
355	      }
356	    }
357	    else {
358	      A2_LOG_DEBUG_EX(EX_EXCEPTION_CAUGHT, err);
359	    }
360	    onAbort();
361	    tryReserved();
362	    return true;
363	  }
364	  catch (DlRetryEx& err) {
365	    assert(req_);
366	    A2_LOG_INFO_EX(
367	        fmt(MSG_RESTARTING_DOWNLOAD, getCuid(), req_->getUri().c_str()),
368	        DL_RETRY_EX2(fmt("URI=%s", req_->getCurrentUri().c_str()), err));
369	    req_->addTryCount();
370	    req_->resetRedirectCount();
371	    req_->resetUri();
372	
373	    const int maxTries = getOption()->getAsInt(PREF_MAX_TRIES);
374	    bool isAbort = maxTries != 0 && req_->getTryCount() >= maxTries;
375	    if (isAbort) {
376	      A2_LOG_INFO(fmt(MSG_MAX_TRY, getCuid(), req_->getTryCount()));
377	      A2_LOG_ERROR_EX(
378	          fmt(MSG_DOWNLOAD_ABORTED, getCuid(), req_->getUri().c_str()), err);
379	      fileEntry_->addURIResult(req_->getUri(), err.getErrorCode());
380	      requestGroup_->setLastErrorCode(err.getErrorCode(), err.what());
381	      if (err.getErrorCode() == error_code::CANNOT_RESUME) {
382	        requestGroup_->increaseResumeFailureCount();
383	      }
384	      onAbort();
385	      tryReserved();
386	      return true;
387	    }
388	
389	    if (err.getErrorCode() == error_code::HTTP_SERVICE_UNAVAILABLE) {
390	      Timer wakeTime(global::wallclock());
391	      wakeTime.advance(
392	          std::chrono::seconds(getOption()->getAsInt(PREF_RETRY_WAIT)));
393	      req_->setWakeTime(wakeTime);
394	    }
395	
396	    return prepareForRetry(0);
397	  }
398	  catch (DownloadFailureException& err) {
399	    requestGroup_->setLastErrorCode(err.getErrorCode(), err.what());
400	    if (req_) {
401	      A2_LOG_ERROR_EX(
402	          fmt(MSG_DOWNLOAD_ABORTED, getCuid(), req_->getUri().c_str()),
403	          DL_ABORT_EX2(fmt("URI=%s", req_->getCurrentUri().c_str()), err));
404	      fileEntry_->addURIResult(req_->getUri(), err.getErrorCode());
405	    }
406	    else {
407	      A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, err);
408	    }
409	    requestGroup_->setHaltRequested(true);
410	    getDownloadEngine()->setRefreshInterval(std::chrono::milliseconds(0));
411	    return true;
412	  }
413	}
