415	void AbstractCommand::tryReserved()
416	{
417	  if (getDownloadContext()->getFileEntries().size() == 1) {
418	    const auto& entry = getDownloadContext()->getFirstFileEntry();
419	    // Don't create new command if currently file length is unknown
420	    // and there are no URI left. Because file length is unknown, we
421	    // can assume that there are no in-flight request object.
422	    if (entry->getLength() == 0 && entry->getRemainingUris().empty()) {
423	      A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Not trying next request."
424	                       " No reserved/pooled request is remaining and"
425	                       " total length is still unknown.",
426	                       getCuid()));
427	      return;
428	    }
429	  }
430	  A2_LOG_DEBUG(
431	      fmt("CUID#%" PRId64 " - Trying reserved/pooled request.", getCuid()));
432	  std::vector<std::unique_ptr<Command>> commands;
433	  requestGroup_->createNextCommand(commands, e_, 1);
434	  e_->setNoWait(true);
435	  e_->addCommand(std::move(commands));
436	}
437	
438	bool AbstractCommand::prepareForRetry(time_t wait)
439	{
440	  if (getPieceStorage()) {
441	    getSegmentMan()->cancelSegment(getCuid());
442	  }
443	  if (req_) {
444	    // Reset persistentConnection and maxPipelinedRequest to handle
445	    // the situation where remote server returns Connection: close
446	    // after several pipelined requests.
447	    req_->supportsPersistentConnection(true);
448	    req_->setMaxPipelinedRequest(1);
449	
450	    fileEntry_->poolRequest(req_);
451	    A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Pooling request URI=%s", getCuid(),
452	                     req_->getUri().c_str()));
453	    if (getSegmentMan()) {
454	      getSegmentMan()->recognizeSegmentFor(fileEntry_);
455	    }
456	  }
457	
458	  auto command =
459	      make_unique<CreateRequestCommand>(getCuid(), requestGroup_, e_);
460	  if (wait == 0) {
461	    e_->setNoWait(true);
462	  }
463	  else {
464	    // We don't use wait so that Command can be executed by
465	    // DownloadEngine::setRefreshInterval(std::chrono::milliseconds(0)).
466	    command->setStatus(Command::STATUS_INACTIVE);
467	  }
468	  e_->addCommand(std::move(command));
469	  return true;
470	}
471	
472	void AbstractCommand::onAbort()
473	{
474	  if (req_) {
475	    fileEntry_->removeIdenticalURI(req_->getUri());
476	    fileEntry_->removeRequest(req_);
477	  }
478	
479	  A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Aborting download", getCuid()));
480	  if (!getPieceStorage()) {
481	    return;
482	  }
483	
484	  getSegmentMan()->cancelSegment(getCuid());
485	  // Don't do following process if BitTorrent is involved or files
486	  // in DownloadContext is more than 1. The latter condition is
487	  // limitation of current implementation.
488	  if (getOption()->getAsBool(PREF_ALWAYS_RESUME) || !fileEntry_ ||
489	      getDownloadContext()->getNetStat().getSessionDownloadLength() != 0 ||
490	      requestGroup_->p2pInvolved() ||
491	      getDownloadContext()->getFileEntries().size() != 1) {
492	    return;
493	  }
494	
495	  const int maxTries = getOption()->getAsInt(PREF_MAX_RESUME_FAILURE_TRIES);
496	  if (!(maxTries > 0 && requestGroup_->getResumeFailureCount() >= maxTries) &&
497	      !fileEntry_->emptyRequestUri()) {
498	    return;
499	  }
500	  // Local file exists, but given servers(or at least contacted
501	  // ones) doesn't support resume. Let's restart download from
502	  // scratch.
503	  A2_LOG_NOTICE(fmt(_("CUID#%" PRId64 " - Failed to resume download."
504	                      " Download from scratch."),
505	                    getCuid()));
506	  A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Gathering URIs that has CANNOT_RESUME"
507	                   " error",
508	                   getCuid()));
509	  // Set PREF_ALWAYS_RESUME to A2_V_TRUE to avoid repeating this
510	  // process.
511	  getOption()->put(PREF_ALWAYS_RESUME, A2_V_TRUE);
512	  std::deque<URIResult> res;
513	  fileEntry_->extractURIResult(res, error_code::CANNOT_RESUME);
514	  if (res.empty()) {
515	    return;
516	  }
517	
518	  getSegmentMan()->cancelAllSegments();
519	  getSegmentMan()->eraseSegmentWrittenLengthMemo();
520	  getPieceStorage()->markPiecesDone(0);
521	  std::vector<std::string> uris;
522	  uris.reserve(res.size());
523	  std::transform(std::begin(res), std::end(res), std::back_inserter(uris),
524	                 std::mem_fn(&URIResult::getURI));
525	  A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - %lu URIs found.", getCuid(),
526	                   static_cast<unsigned long int>(uris.size())));
527	  fileEntry_->addUris(std::begin(uris), std::end(uris));
528	  getSegmentMan()->recognizeSegmentFor(fileEntry_);
529	}
