625	namespace {
626	// Constructs proxy URI, merging username and password if they are
627	// defined.
628	std::string makeProxyUri(PrefPtr proxyPref, PrefPtr proxyUser,
629	                         PrefPtr proxyPasswd, const Option* option)
630	{
631	  uri::UriStruct us;
632	  if (!uri::parse(us, option->get(proxyPref))) {
633	    return "";
634	  }
635	  if (option->defined(proxyUser)) {
636	    us.username = option->get(proxyUser);
637	  }
638	  if (option->defined(proxyPasswd)) {
639	    us.password = option->get(proxyPasswd);
640	    us.hasPassword = true;
641	  }
642	  return uri::construct(us);
643	}
644	} // namespace
645	
646	namespace {
647	// Returns proxy option value for the given protocol.
648	std::string getProxyOptionFor(PrefPtr proxyPref, PrefPtr proxyUser,
649	                              PrefPtr proxyPasswd, const Option* option)
650	{
651	  std::string uri = makeProxyUri(proxyPref, proxyUser, proxyPasswd, option);
652	  if (uri.empty()) {
653	    return makeProxyUri(PREF_ALL_PROXY, PREF_ALL_PROXY_USER,
654	                        PREF_ALL_PROXY_PASSWD, option);
655	  }
656	
657	  return uri;
658	}
659	} // namespace
660	
661	// Returns proxy URI for given protocol.  If no proxy URI is defined,
662	// then returns an empty string.
663	std::string getProxyUri(const std::string& protocol, const Option* option)
664	{
665	  if (protocol == "http") {
666	    return getProxyOptionFor(PREF_HTTP_PROXY, PREF_HTTP_PROXY_USER,
667	                             PREF_HTTP_PROXY_PASSWD, option);
668	  }
669	
670	  if (protocol == "https") {
671	    return getProxyOptionFor(PREF_HTTPS_PROXY, PREF_HTTPS_PROXY_USER,
672	                             PREF_HTTPS_PROXY_PASSWD, option);
673	  }
674	
675	  if (protocol == "ftp" || protocol == "sftp") {
676	    return getProxyOptionFor(PREF_FTP_PROXY, PREF_FTP_PROXY_USER,
677	                             PREF_FTP_PROXY_PASSWD, option);
678	  }
679	
680	  return A2STR::NIL;
681	}
