683	namespace {
684	// Returns true if proxy is defined for the given protocol. Otherwise
685	// returns false.
686	bool isProxyRequest(const std::string& protocol,
687	                    const std::shared_ptr<Option>& option)
688	{
689	  std::string proxyUri = getProxyUri(protocol, option.get());
690	  return !proxyUri.empty();
691	}
