694	namespace {
695	bool inNoProxy(const std::shared_ptr<Request>& req, const std::string& noProxy)
696	{
697	  std::vector<Scip> entries;
698	  util::splitIter(std::begin(noProxy), std::end(noProxy),
699	                  std::back_inserter(entries), ',', true);
700	  if (entries.empty()) {
701	    return false;
702	  }
703	
704	  for (const auto& e : entries) {
705	    const auto slashpos = std::find(e.first, e.second, '/');
706	    if (slashpos == e.second) {
707	      if (util::noProxyDomainMatch(req->getHost(),
708	                                   std::string(e.first, e.second))) {
709	        return true;
710	      }
711	
712	      continue;
713	    }
714	    // TODO We don't resolve hostname here.  More complete
715	    // implementation is that we should first resolve
716	    // hostname(which may result in several IP addresses) and
717	    // evaluates against all of them
718	    std::string ip(e.first, slashpos);
719	    uint32_t bits;
720	    if (!util::parseUIntNoThrow(bits, std::string(slashpos + 1, e.second))) {
721	      continue;
722	    }
723	    if (util::inSameCidrBlock(ip, req->getHost(), bits)) {
724	      return true;
725	    }
726	  }
727	  return false;
728	}
729	} // namespace
