737	std::shared_ptr<Request> AbstractCommand::createProxyRequest() const
738	{
739	  std::shared_ptr<Request> proxyRequest;
740	  if (inNoProxy(req_, getOption()->get(PREF_NO_PROXY))) {
741	    return proxyRequest;
742	  }
743	
744	  std::string proxy = getProxyUri(req_->getProtocol(), getOption().get());
745	  if (!proxy.empty()) {
746	    proxyRequest = std::make_shared<Request>();
747	    if (proxyRequest->setUri(proxy)) {
748	      A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Using proxy", getCuid()));
749	    }
750	    else {
751	      A2_LOG_DEBUG(
752	          fmt("CUID#%" PRId64 " - Failed to parse proxy string", getCuid()));
753	      proxyRequest.reset();
754	    }
755	  }
756	  return proxyRequest;
757	}
