759	std::string AbstractCommand::resolveHostname(std::vector<std::string>& addrs,
760	                                             const std::string& hostname,
761	                                             uint16_t port)
762	{
763	  if (util::isNumericHost(hostname)) {
764	    addrs.push_back(hostname);
765	    return hostname;
766	  }
767	
768	  e_->findAllCachedIPAddresses(std::back_inserter(addrs), hostname, port);
769	  if (!addrs.empty()) {
770	    auto ipaddr = addrs.front();
771	    A2_LOG_INFO(fmt(MSG_DNS_CACHE_HIT, getCuid(), hostname.c_str(),
772	                    strjoin(std::begin(addrs), std::end(addrs), ", ").c_str()));
773	    return ipaddr;
774	  }
775	
776	  std::string ipaddr;
777	#ifdef ENABLE_ASYNC_DNS
778	  if (getOption()->getAsBool(PREF_ASYNC_DNS)) {
779	    if (!asyncNameResolverMan_->started()) {
780	      asyncNameResolverMan_->startAsync(hostname, e_, this);
781	    }
782	    switch (asyncNameResolverMan_->getStatus()) {
783	    case -1:
784	      if (!isProxyRequest(req_->getProtocol(), getOption())) {
785	        e_->getRequestGroupMan()
786	            ->getOrCreateServerStat(req_->getHost(), req_->getProtocol())
787	            ->setError();
788	      }
789	      throw DL_ABORT_EX2(fmt(MSG_NAME_RESOLUTION_FAILED, getCuid(),
790	                             hostname.c_str(),
791	                             asyncNameResolverMan_->getLastError().c_str()),
792	                         error_code::NAME_RESOLVE_ERROR);
793	    case 0:
794	      return A2STR::NIL;
795	
796	    case 1:
797	      asyncNameResolverMan_->getResolvedAddress(addrs);
798	      if (addrs.empty()) {
799	        throw DL_ABORT_EX2(fmt(MSG_NAME_RESOLUTION_FAILED, getCuid(),
800	                               hostname.c_str(), "No address returned"),
801	                           error_code::NAME_RESOLVE_ERROR);
802	      }
803	      break;
804	    }
805	  }
806	  else
807	#endif // ENABLE_ASYNC_DNS
808	  {
809	    NameResolver res;
810	    res.setSocktype(SOCK_STREAM);
811	    if (e_->getOption()->getAsBool(PREF_DISABLE_IPV6)) {
812	      res.setFamily(AF_INET);
813	    }
814	    res.resolve(addrs, hostname);
815	  }
816	  A2_LOG_INFO(fmt(MSG_NAME_RESOLUTION_COMPLETE, getCuid(), hostname.c_str(),
817	                  strjoin(std::begin(addrs), std::end(addrs), ", ").c_str()));
818	  for (const auto& addr : addrs) {
819	    e_->cacheIPAddress(hostname, addr, port);
820	  }
821	  ipaddr = e_->findCachedIPAddress(hostname, port);
822	  return ipaddr;
823	}
