835	bool AbstractCommand::checkIfConnectionEstablished(
836	    const std::shared_ptr<SocketCore>& socket,
837	    const std::string& connectedHostname, const std::string& connectedAddr,
838	    uint16_t connectedPort)
839	{
840	  std::string error = socket->getSocketError();
841	  if (error.empty()) {
842	    return true;
843	  }
844	
845	  // See also InitiateConnectionCommand::executeInternal()
846	  e_->markBadIPAddress(connectedHostname, connectedAddr, connectedPort);
847	  if (e_->findCachedIPAddress(connectedHostname, connectedPort).empty()) {
848	    e_->removeCachedIPAddress(connectedHostname, connectedPort);
849	    // Don't set error if proxy server is used and its method is GET.
850	    if (resolveProxyMethod(req_->getProtocol()) != V_GET ||
851	        !isProxyRequest(req_->getProtocol(), getOption())) {
852	      e_->getRequestGroupMan()
853	          ->getOrCreateServerStat(req_->getHost(), req_->getProtocol())
854	          ->setError();
855	    }
856	    throw DL_RETRY_EX(fmt(MSG_ESTABLISHING_CONNECTION_FAILED, error.c_str()));
857	  }
858	
859	  A2_LOG_INFO(fmt(MSG_CONNECT_FAILED_AND_RETRY, getCuid(),
860	                  connectedAddr.c_str(), connectedPort));
861	  e_->setNoWait(true);
862	  e_->addCommand(
863	      InitiateConnectionCommandFactory::createInitiateConnectionCommand(
864	          getCuid(), req_, fileEntry_, requestGroup_, e_));
865	  return false;
866	}
