68	bool CreateRequestCommand::executeInternal()
69	{
70	  if (getSegments().empty()) {
71	    setFileEntry(getDownloadContext()->findFileEntryByOffset(0));
72	  }
73	  else {
74	    // We assume all segments belongs to same file.
75	    setFileEntry(getDownloadContext()->findFileEntryByOffset(
76	        getSegments().front()->getPositionToWrite()));
77	  }
78	  std::vector<std::pair<size_t, std::string>> usedHosts;
79	  if (getOption()->getAsBool(PREF_SELECT_LEAST_USED_HOST)) {
80	    getDownloadEngine()->getRequestGroupMan()->getUsedHosts(usedHosts);
81	  }
82	  setRequest(
83	      getFileEntry()->getRequest(getRequestGroup()->getURISelector().get(),
84	                                 getOption()->getAsBool(PREF_REUSE_URI),
85	                                 usedHosts, getOption()->get(PREF_REFERER),
86	                                 // Don't use HEAD request when file
87	                                 // size is known.
88	                                 // Use HEAD for dry-run mode.
89	                                 (getFileEntry()->getLength() == 0 &&
90	                                  getOption()->getAsBool(PREF_USE_HEAD)) ||
91	                                         getOption()->getAsBool(PREF_DRY_RUN)
92	                                     ? Request::METHOD_HEAD
93	                                     : Request::METHOD_GET));
94	  if (!getRequest()) {
95	    if (getSegmentMan()) {
96	      getSegmentMan()->ignoreSegmentFor(getFileEntry());
97	    }
98	    if (getOption()->getAsBool(PREF_DRY_RUN)) {
99	      // For dry run mode, just throwing DlAbortEx makes infinite
100	      // loop, since we don't have SegmentMan, and we cannot tell all
101	      // hopes were abandoned.
102	      throw DOWNLOAD_FAILURE_EXCEPTION2("No URI available.",
103	                                        getRequestGroup()->getLastErrorCode());
104	    }
105	    // In this case, the error might be already set in RequestGroup,
106	    // so use it here.
107	    throw DL_ABORT_EX2("No URI available.",
108	                       getRequestGroup()->getLastErrorCode());
109	  }
110	  else if (getRequest()->getWakeTime() > global::wallclock()) {
111	    A2_LOG_DEBUG("This request object is still sleeping.");
112	    getFileEntry()->poolRequest(getRequest());
113	    // Reset request of this command. Without this, request is doubly
114	    // counted (1 for pooled and another one in this command) and
115	    // AbstractCommand::execute() will behave badly.
116	    resetRequest();
117	    addCommandSelf();
118	    return false;
119	  }
120	
121	  getDownloadEngine()->setNoWait(true);
122	  getDownloadEngine()->addCommand(
123	      InitiateConnectionCommandFactory::createInitiateConnectionCommand(
124	          getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
125	          getDownloadEngine()));
126	  return true;
127	}
